const test=require('node:test');
const assert=require('node:assert/strict');
const {maskAccount}=require('../privacy.cjs');
test('code points and zero',()=>{
  assert.equal(maskAccount('A🚲BC',2),'**BC');
  assert.equal(maskAccount('AB🚲',1),'**🚲');
  assert.equal(maskAccount('abc',0),'***');
  assert.equal(maskAccount('abc',9),'abc');
  assert.equal(maskAccount('123456'),'**3456');
  assert.equal(maskAccount('',0),'');
  assert.equal(maskAccount('e\u0301x',1),'**x');
});
test('invalid visible count',()=>{
  for(const value of [-1,1.5,NaN]) assert.throws(()=>maskAccount('abc',value),RangeError);
});

