exports.maskAccount = function(text, visible=4) {
  if (!Number.isInteger(visible) || visible < 0) throw new RangeError('invalid visible count');
  const chars=Array.from(text);
  const hidden=Math.max(0,chars.length-visible);
  return '*'.repeat(hidden)+chars.slice(hidden).join('');
};

